// Monochrome-black SVGs that need inversion to white on dark pills.
const INVERT = new Set(["/icons/ollama.svg", "/icons/langchain.svg", "/icons/express.svg", "/icons/posthog.svg", "/icons/freecodecamp.svg", "/icons/github.svg", "/icons/githubcopilot.svg", "/icons/opencode.svg", "/icons/openai.svg", "/icons/gitlens.svg"])

export function ItemIcon({ icon }) {
  if (!icon) return null
  if (icon.startsWith("/")) {
    return (
      <img
        src={icon}
        alt=""
        aria-hidden="true"
        loading="lazy"
        className={`h-[18px] w-auto max-w-[38px] shrink-0 ${INVERT.has(icon) ? "dark:invert" : ""}`}
      />
    )
  }
  const LucideIcon = LUCIDE_ICONS[icon]
  if (!LucideIcon) return null
  return <LucideIcon className="h-[18px] w-[18px] shrink-0 text-primary" aria-hidden="true" />
}

export function StackPill({ icon, label }) {
  return (
    <span className="inline-flex cursor-default items-center gap-2 rounded-md border border-border/70 px-3 py-1.5 text-sm font-medium text-foreground/90 transition-colors duration-200 hover:border-primary/60 hover:text-primary">
      <ItemIcon icon={icon} />
      {label}
    </span>
  )
}
